  fs.writeFileSync(path.join(gdir, V2), gcode({ day: 2, est: "1h 12m", changes: 12, colors: "#FF0000;#00FF00", types: "PLA;PLA", grams: "10;5", cfg: { retraction_length: "1.2", outer_wall_speed: "150", enable_prime_tower: "1" } }));
