  const regal = gcode({ day: 4, est: "6h 16m", grams: "180" });
  fs.writeFileSync(path.join(gdir, REGAL), regal); fs.writeFileSync(path.join(kdir, REGAL_DUP), regal);
  fs.writeFileSync(path.join(gdir, LONELY), gcode({ day: 5, est: "2h 0m" }));
