  fs.writeFileSync(path.join(gdir, HUGE), gcode({ day: 6, est: "3h 0m", cfg: bigCfg, body: Array(300).fill("G1 X1 Y1 E0.1") }));
  fs.writeFileSync(path.join(kdir, KOBRA), gcode({ day: 7, est: "2h 0m", types: "PETG", cfg: { printer_model: "Anycubic Kobra S1", nozzle_temperature: "240" } }));
