  fs.writeFileSync(path.join(mdir, "Yosh", "Sakura Framed", "Sakura Framed.3mf"), sak); fs.writeFileSync(path.join(mdir, "Downloads", "Sakura Framed (1).3mf"), sak);
  fs.mkdirSync(path.join(mdir, "Yosh", "Other Model"), { recursive: true }); fs.writeFileSync(path.join(mdir, "Yosh", "Other Model", "Other Model.3mf"), threeMf({ title: "Other Model" }));
  const deepDir = path.join(mdir, "Yosh", "Aug26", "Collectibles", "Game", "Poster", "Mini"); fs.mkdirSync(deepDir, { recursive: true }); fs.writeFileSync(path.join(deepDir, "Deep Poster.3mf"), threeMf({ title: "Deep Poster", printer: "Bambu Lab X1 Carbon" }));
